using Ranki.Services.Interfaces;
using System.Text.Json; using Microsoft.Extensions.Configuration;  namespace Ranki.Services.Implementations {     public interface IGeminiClient     {         Task<string> GenerateContentAsync(string prompt);     }      public class GeminiClient : IGeminiClient     {         private readonly HttpClient _httpClient;         private readonly string _apiKey;          public GeminiClient(HttpClient httpClient, IConfiguration config)         {             _httpClient = httpClient;             _apiKey = config["Gemini:ApiKey"] ?? throw new ArgumentNullException("Gemini:ApiKey missing");         }          public async Task<string> GenerateContentAsync(string prompt)         {             var url = $"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={_apiKey}";             var requestBody = new             {                 contents = new[]                 {                     new                     {                         parts = new[] { new { text = prompt } }                     }                 }             };              var response = await _httpClient.PostAsJsonAsync(url, requestBody);             response.EnsureSuccessStatusCode();              var responseJson = await response.Content.ReadAsStringAsync();             var doc = JsonDocument.Parse(responseJson);             var text = doc.RootElement                 .GetProperty("candidates")[0]                 .GetProperty("content")                 .GetProperty("parts")[0]                 .GetProperty("text").GetString();              return text ?? string.Empty;         }     } }
